{
  "strategy": "user_scenario",
  "duration_s": 30,
  "segments": [
    {
      "index": 1,
      "time_range": "0-3s",
      "visual": "竖屏快切：宿舍书桌前的手机屏幕播放学习打卡片段（笔记+计时器），随后切到校园操场、教室的简短镜头，制造“这些片段怎么卡点”的钩子。情境画面来自 M-005，后续由运营从素材包中选取教室/宿舍场景各1条10-15秒片段。",
      "audio": "轻快背景音乐（待获取授权，暂用试听版占位；若未获授权则改用已授权曲目）",
      "subtitle": "学习打卡素材，怎么卡点更顺？",
      "material_ids": ["M-005", "M-006"],
      "evidence_ids": ["E1"]
    },
    {
      "index": 2,
      "time_range": "4-15s",
      "visual": "帧剪 iOS/Android 4.2+ 操作录屏（待制作，运营负责录制）：导入学习打卡素材→选择音乐→点击“自动卡点”→时间线片段自动对齐节拍点；画面同步用字幕标出“自动分析音乐节拍，对齐到节拍点”。需核对界面无实验性功能入口。",
      "audio": "背景音乐持续，卡点对齐瞬间加轻微“嗒”音效（音效待制作/获取授权）",
      "subtitle": "自动卡点：分析音乐节拍，把选中片段对齐到节拍点",
      "material_ids": [],
      "evidence_ids": ["E1"]
    },
    {
      "index": 3,
      "time_range": "16-24s",
      "visual": "同一录屏继续（待制作）：手势拖动某一段片段，逐段微调到更准的节拍位置；再点击“一键重新卡点”演示可恢复自动对齐。字幕提示“逐段微调 / 一键重新卡点”。",
      "audio": "背景音乐持续，微调操作配轻微点击音效（待制作/获取授权）",
      "subtitle": "可逐段微调，也可一键重新卡点",
      "material_ids": [],
      "evidence_ids": ["E1", "E3"]
    },
    {
      "index": 4,
      "time_range": "25-30s",
      "visual": "成片预览：学习打卡片段随节拍切换，画面回到校园情境（M-005 操作台/宿舍场景），叠加文字“自动卡点 + 逐段微调，卡点自己说了算”。结尾品牌标版（待制作）。",
      "audio": "背景音乐渐弱收尾（授权状态同上）",
      "subtitle": "自动卡点 + 逐段微调，卡点自己说了算",
      "material_ids": ["M-005", "M-006"],
      "evidence_ids": ["E1", "E2"]
    }
  ],
  "claims": [
    {
      "id": "E1",
      "claim": "自动卡点会分析音乐节拍，把选中视频片段对齐到节拍点；用户可逐段微调，也可一键重新卡点。",
      "material_id": "M-001",
      "quote": "自动卡点会分析所选音乐的节拍，把用户选中的视频片段对齐到节拍点。用户可以逐段微调，也可以一键重新卡点。",
      "scope": "iOS/Android 4.2 及以上；支持15/30/60秒成片；对节奏清晰的流行乐与鼓点识别更稳"
    },
    {
      "id": "E2",
      "claim": "复杂变速或弱节拍音乐需要人工调整，脚本以节奏清晰曲目演示，不承诺所有曲风都准确。",
      "material_id": "M-001",
      "quote": "该功能不承诺对所有曲风都准确，复杂变速或弱节拍音乐需要人工调整。",
      "scope": "所有使用场景"
    },
    {
      "id": "E3",
      "claim": "对外表达轻快、真实、可操作，不承诺涨粉、收益或爆款，不使用“最强”“唯一”等绝对化表述。",
      "material_id": "M-004",
      "quote": "表达应轻快、真实、可操作。不得承诺涨粉、收益或爆款；不得把实验性功能写成正式能力；不得使用‘最强’‘唯一’等绝对化表述；涉及未成年人时避免诱导消费。",
      "scope": "适用于所有对外传播；与用户明确要求冲突时交回用户决定"
    }
  ],
  "open_questions": [
    {
      "question": "背景音乐《Late Bus》商用授权是否由运营按2个工作日采购，或改用其他已授权120 BPM曲目？",
      "impact": "影响第1、2、3、4段配乐与卡点演示节拍；未落实需替换曲目并重新核对卡点效果",
      "blocking": false
    },
    {
      "question": "操作录屏由谁录制、在何版本设备上录制、是否需要露出手指操作？",
      "impact": "影响第2、3段录屏素材制作排期与剪辑精细度；未完成则第2、3段无法按计划呈现",
      "blocking": false
    },
    {
      "question": "音乐采购、录屏制作与投放费用未给出，需由运营单列估算。",
      "impact": "活动真实成本未知，本方案不承诺金额",
      "blocking": false
    }
  ]
}
